#include "ReferenceReview.h"
#include "ContextFit.h"
#include "Refinement.h"
#include "ModelCodec.h"
#include <iostream>
#include <stdexcept>
void check(bool ok,const char* message){if(!ok)throw std::runtime_error(message);}
nova::Sound phrase(){nova::Sound s;s.sampleRate=16000;s.left.resize(192000);s.right=s.left;int notes[]={48,55,60,64,67,72};for(size_t i=0;i<s.left.size();++i){double t=i/s.sampleRate;int slot=std::min(5,static_cast<int>(t/2));double local=t-slot*2;if(local>1.7)continue;double hz=440*std::pow(2.,(notes[slot]-69)/12.),envelope=std::min(1.,local/.015)*std::min(1.,(1.7-local)/.06);s.left[i]=s.right[i]=static_cast<float>((slot%2?.13:.3)*envelope*std::sin(2*nova::pi*hz*local));}return s;}
nova::SpectralModel model(int root){nova::SpectralModel m;m.root=root;m.count=4;m.duration=.4;for(int i=0;i<nova::modelFrames;++i)m.times[i]=i*m.duration/(nova::modelFrames-1);double hz=440*std::pow(2.,(root-69)/12.);for(int p=0;p<4;++p){m.partials[p].frequency=hz*(p==3?2.43:p+1);m.partials[p].amplitude.fill(p==0?.2f:p==3?.015f:.07f);m.partials[p].frequencyRatio.fill(1);}return m;}
nova::Params patch(){nova::Params p;p.engine=1;p.root=69;p.unison=false;p.sub=p.fm=p.noise=p.detune=p.fineTune=p.lfoDepth=p.delay=p.reverb=p.chorus=p.drive=0;p.tracking=p.residual=0;p.master=-9;return p;}
nova::RefineExample example(nova::Params p,const std::shared_ptr<nova::SpectralModel>& m,const std::shared_ptr<nova::ZoneBank>& bank,int note,float velocity){nova::Sound ref;ref.sampleRate=22050;ref.left.resize(8820);ref.right=ref.left;nova::Engine e;e.configure(p);e.prepare(ref.sampleRate);e.setModel(m.get());e.setZoneBank(bank.get());e.noteOn(1,note,velocity);e.render(ref.left.data(),ref.right.data(),static_cast<int>(ref.left.size()));nova::analyse(ref);check(ref.tonal,"reference model has stable pitch");return {nova::makeTarget(ref,note,22050,false),velocity};}
int main(){try{
 std::atomic<bool> cancel{false};auto source=phrase();float before=0;auto review=nova::reviewReference(source,cancel,[&](float progress){check(progress>=before&&progress<=1,"review progress monotonic");before=progress;});check(review.rows.size()>=6&&review.analysis.uniqueNotes==6&&before==1,"review covers six registers");auto recommended=nova::recommendedRows(review);check(recommended.size()>=4&&recommended.size()<=8,"bounded informative recommendations");for(int i:recommended)check(review.rows[i].stable(),"only stable unclipped recommendations");
 std::vector<int> chosen={recommended[1],recommended[3]};auto selected=nova::chosenReviewNotes(review,chosen);check(selected.picked.size()==2&&selected.picked[0].range.start==review.rows[chosen[0]].note.range.start,"manual choices do not refill excluded notes");auto learned=nova::fitContextNotes(source,35.5,selected,80,cancel);check(learned.fit.valid&&learned.bank&&learned.bank->count==2,"only two chosen notes learned");for(const auto& n:learned.analysis.picked)check(n.range.start>=35.5&&n.range.end<=47.5,"reviewed source positions offset exactly");check(nova::chosenReviewNotes(review,std::vector<int>(9,0)).picked.empty(),"over-limit selection rejected");check(nova::chosenReviewNotes(review,{chosen[0],chosen[0],-1,9999}).picked.size()==1,"duplicate/out-of-range choice handling");
 auto clipped=source;for(size_t i=0;i<27200;++i)clipped.left[i]=clipped.right[i]=std::clamp(clipped.left[i]*6,-1.f,1.f);auto bad=nova::reviewReference(clipped,cancel);check(bad.clipped>.001&&bad.summary.find("recortados")!=std::string::npos,"global clipping warning");bool flagged=false;for(const auto& row:bad.rows)if(row.note.range.start<1.5&&row.clipped>.001){flagged=true;check(!row.recommended&&!row.stable(),"clipped candidate excluded from recommendations");}check(flagged,"clipped row remains visible for review");
 cancel.store(true);check(nova::reviewReference(source,cancel).cancelled,"review cancellation");cancel.store(false);
 auto m=std::make_shared<nova::SpectralModel>(model(69));auto bytes=nova::encodeModel(*m);auto desired=patch();auto ref=example(desired,m,nullptr,69,.8f);auto initial=desired;initial.spectralTone=.7;initial.spectralTime=1.25;initial.eqHigh=4;initial.eqOn=true;
 for(auto goal:{nova::RefineGoal::balanced,nova::RefineGoal::attack,nova::RefineGoal::body,nova::RefineGoal::lessMetallic,nova::RefineGoal::lessEffects}){int last=0;auto fit=nova::refineInstrument({ref},initial,m,nullptr,goal,120,cancel,[&](int n,int total,double){check(n>=last&&n<=total,"refinement progress bounded");last=n;});check(fit.fit.valid&&!fit.fit.cancelled&&fit.fit.trials==120,"refinement completes");check(fit.objectiveAfter<=fit.objectiveBefore+1e-9,"chosen objective never worsens");check(fit.fit.parameters.engine==initial.engine&&fit.fit.parameters.root==initial.root&&fit.fit.parameters.fineTune==initial.fineTune&&fit.fit.parameters.transpose==initial.transpose,"engine and tuning mapping preserved");if(goal==nova::RefineGoal::body)check(fit.after.body<=fit.before.body+1e-7,"body preserved by explicit guard");if(goal==nova::RefineGoal::balanced)check(fit.objectiveAfter<fit.objectiveBefore*.95,"controlled mismatch meaningfully improves");std::cout<<"goal "<<static_cast<int>(goal)<<" "<<fit.objectiveBefore<<" -> "<<fit.objectiveAfter<<'\n';}
 check(bytes==nova::encodeModel(*m),"reference model immutable, no PCM or in-place edits");
 auto bank=std::make_shared<nova::ZoneBank>();bank->count=2;bank->zones[0]={model(48),.3};bank->zones[1]={model(72),.9};desired.useZones=true;auto low=example(desired,m,bank,48,.3f),high=example(desired,m,bank,72,.9f);initial=desired;initial.spectralTone=.6f;auto multi=nova::refineInstrument({low,high},initial,m,bank,nova::RefineGoal::balanced,100,cancel);check(multi.fit.valid&&multi.examples==2&&multi.fit.parameters.useZones&&multi.objectiveAfter<multi.objectiveBefore,"both note/velocity zones contribute to refinement");
 auto stopped=nova::refineInstrument({ref},initial,m,bank,nova::RefineGoal::balanced,80,cancel,[&](int n,int,double){if(n==3)cancel.store(true);});check(stopped.fit.cancelled&&!stopped.fit.valid,"cancelled refinement cannot apply");cancel.store(false);nova::RefineExample silent=ref;std::fill(silent.target.left.begin(),silent.target.left.end(),0);std::fill(silent.target.right.begin(),silent.target.right.end(),0);check(!nova::refineInstrument({silent},initial,m,nullptr,nova::RefineGoal::balanced,30,cancel).fit.valid,"silent targets rejected");
 std::cout<<"PASS: review/selection/exclusion/clipping/cancel, reviewed bank, four refinement goals, pitch lock, immutable model, multizone objective, improvement and silent rejection\n";
}catch(const std::exception& e){std::cerr<<"FAIL: "<<e.what()<<'\n';return 1;}}
